from functools import lru_cache
from itertools import combinations
price = [0,800,1520,2160,2560,3000]

def all_subsets(state):
    state=tuple(state)
    @lru_cache(None)
    def f(st):
        if not any(st): return 0
        best=sum(x*800 for x in st)
        # all subsets of positive title indices
        for mask in range(1,32):
            s=mask.bit_count()
            if s<2: continue
            if all(st[i]>0 for i in range(5) if mask>>i & 1):
                nxt=list(st)
                for i in range(5):
                    if mask>>i & 1: nxt[i]-=1
                cost=price[s]+f(tuple(nxt))
                if cost<best: best=cost
        return best
    return f(state)

def high_groups(state):
    state=tuple(sorted(state, reverse=True))
    @lru_cache(None)
    def f(st):
        st=tuple(sorted(st, reverse=True))
        if not any(st): return 0
        best=sum(x*800 for x in st)
        for s in range(2,6):
            if sum(1 for x in st if x>0)>=s:
                nxt=list(st)
                for i in range(s):
                    nxt[i]-=1
                cost=price[s]+f(tuple(nxt))
                if cost<best: best=cost
        return best
    return f(state)

for N in range(0,6):
    bad=[]
    import itertools
    for st in itertools.product(range(N+1), repeat=5):
        a=all_subsets(st)
        b=high_groups(st)
        if a!=b:
            bad.append((st,a,b))
            if len(bad)>=5: break
    print('N',N,'bad',len(bad),bad[:5])
